@media screen and (max-width: 850px) {
  #_cb_ai_search-wrapper {
    display: none;
  }

  /* Reset grid to single column when search is hidden */
  #_cb_ai_search-container {
    grid-template-columns: 1fr;
  }

  #_cb_ai_chat-wrapper {
    grid-column: 1;
  }
}

@media screen and (max-width: 820px) {
  #_cb_ai_container {
    font-size: 16px;
    padding: 28px;
    gap: 28px;
  }

  #_cb_ai_search-container {
    gap: 28px;
  }

  #_bl_chat-box {
    padding: 9px;
  }

  ._bl_message-everlink-tooltip, ._bl_message-everlink-tooltip-right {
    display: none !important;
  }
}

